function printLayoutCss(){
  function walk(rules){return [...rules].map(rule=>{
    if(rule.type===CSSRule.MEDIA_RULE)return /(^|[,\s])print([,\s]|$)/i.test(rule.conditionText)?walk(rule.cssRules):'';
    return rule.cssText;
  }).join('\n');}
  return [...document.styleSheets].map(sheet=>{try{return walk(sheet.cssRules);}catch{return '';}}).join('\n');
}
function rebalanceReportPrintSheet(sheet,doc){
  const number=el=>el?.querySelector(':scope > h3 .num')?.textContent.trim();
  const overview=sheet.querySelector('.overview01'),grid=overview?.querySelector('.overview-grid');
  const heading=overview?.querySelector(':scope > h3'),copy=grid?.querySelector(':scope > .overview-copy'),visuals=grid?.querySelector(':scope > .overview-visuals');
  const life=sheet.querySelector('.life-academics'),lower=sheet.querySelector('.lower-report');
  const sections=life?[...life.querySelectorAll(':scope > .section')]:[];
  const s02=sections.find(el=>number(el)==='02'),s03=sections.find(el=>number(el)==='03');
  const s04=lower?.querySelector('.costs04'),s05=lower?.querySelector('.coaches05'),s06=lower?.querySelector('.personal06');
  if(!overview||!heading||!copy||!visuals||!s02||!s03)return null;
  sheet.classList.add('print-balanced');
  const photos=visuals.querySelector('.campus-photos');
  if(photos&&!photos.classList.contains('verified-photos')){
    const figures=[...photos.querySelectorAll(':scope > figure')].map(figure=>{
      const img=figure.querySelector('img.photo'),caption=figure.querySelector('figcaption')?.textContent||'';
      const text=((img?.alt||'')+' '+caption).toLowerCase();
      const unrelated=/\b(baseball|softball|tennis|golf|pitching|mbb)\b/i.test(text);
      const outdoor=/\b(outdoors?|exterior|outside|aerial)\b/i.test(text);
      const indoor=!unrelated&&!outdoor&&/\b(weight room|weight training|strength|sports performance|fitness center|training facility)\b|ウェイト|ウエイト|筋力トレーニング/i.test(text);
      const soccer=/\b(soccer|football|men.s soccer|match ground|pitch)\b|サッカー|ホームグラウンド|試合会場/i.test(text);
      const ground=!unrelated&&(soccer||figure.classList.contains('stadium')||/\b(field|stadium|pitch|ground)\b|グラウンド/i.test(text));
      const facility=!unrelated&&!ground&&(indoor||figure.classList.contains('facility'));
      const venue=(img?.alt||caption).toLowerCase().replace(/(official|photo|image|view|overview|match|ground|soccer|men.?s|facility|pitch|field|stadium|photo|university|大学公式|男子サッカーのホームグラウンド)/g,'').replace(/[^a-z0-9\u3040-\u30ff\u3400-\u9fff]+/g,' ').trim();
      return{figure,indoor,ground,facility,soccer,venue,unrelated};
    });
    const facility=figures.filter(x=>x.indoor)[0];
    const ground=figures.filter(x=>x.ground).sort((a,b)=>Number(b.soccer)-Number(a.soccer))[0];
    const keep=[];if(facility)keep.push(facility.figure);if(ground&&ground.figure!==facility?.figure)keep.push(ground.figure);
    photos.replaceChildren(...keep);
    if(!keep.length){const figure=doc.createElement('figure'),placeholder=doc.createElement('div'),caption=doc.createElement('figcaption');figure.className='campus-shot';placeholder.className='photo-missing';placeholder.textContent='確認出来ず';caption.textContent='屋内トレーニング施設・男子サッカーのグラウンド写真は確認出来ず';figure.append(placeholder,caption);photos.append(figure);}
  }
  const titleBlock=doc.createElement('section');titleBlock.className='section overview01 print-overview-title';titleBlock.append(heading);
  const columns=doc.createElement('div');columns.className='print-columns';
  const left=doc.createElement('div'),right=doc.createElement('div');left.className='print-column print-column-left';right.className='print-column print-column-right';
  left.append(copy,s02);right.append(visuals,s03);columns.append(left,right);
  const footer=sheet.querySelector(':scope > .sheet-foot');
  const wrappers=new Set([overview,life,lower]);
  const retained=[...sheet.children].filter(el=>!wrappers.has(el)&&el!==footer);
  const qrItems=retained.filter(el=>el.matches('.qr,.qr-row,.qr-links,.report-qr,.official-ig-qr')||el.querySelector('img[alt*="QR"],svg[aria-label*="QR"]'));
  sheet.replaceChildren(...retained.filter(el=>!qrItems.includes(el)),titleBlock,columns,...qrItems,...(footer?[footer]:[]));
  return{left,right,costs:s04,coaches:s05,roster:s06};
}
