async function runReportPrint(id){
  const buttons=[...document.querySelectorAll('.school-actions button,.toc-controls button')];buttons.forEach(b=>b.disabled=true);
  try{const frame=await prepareReportPrint(id);frame.contentWindow.addEventListener('afterprint',()=>{if(activePrintFrame===frame){frame.remove();activePrintFrame=null;}},{once:true});frame.contentWindow.focus();frame.contentWindow.print();}
  catch(error){console.error('Report printing failed',error);if(activePrintFrame){activePrintFrame.remove();activePrintFrame=null;}alert(error.message.startsWith('A4用紙に収まらない')?error.message:'印刷の準備に失敗しました。ページを再読み込みして、もう一度お試しください。');}
  finally{buttons.forEach(b=>b.disabled=false);}
}
function printSchool(id){return runReportPrint(id);}
function printAll(){return runReportPrint();}
function wireImageFallbacks(root){root.querySelectorAll('img.photo,img.staff-photo,.staff img').forEach(img=>img.addEventListener('error',()=>{const box=document.createElement('div');box.className=img.classList.contains('staff-photo')||img.closest('.staff')?'staff-photo-missing':'photo-missing';box.textContent='確認出来ず';box.setAttribute('aria-label','画像を確認出来ず');img.replaceWith(box);},{once:true}));root.querySelectorAll('.section').forEach(section=>{const number=section.querySelector(':scope > h3 .num');if(number?.textContent.trim()==='02'){const label=[...section.querySelectorAll('.topic-label')].find(el=>el.textContent.trim()==='公共交通・都市へのアクセス');const paragraph=label?.closest('p');if(paragraph&&!paragraph.closest('.transit-box'))paragraph.classList.add('transit-box');}});}
function moveTransitReference(sheet){
  const sections=[...sheet.querySelectorAll('.section')];
  const find=n=>sections.find(section=>section.querySelector(':scope > h3 .num')?.textContent.trim()===n);
  const housing=find('02'),costs=find('04');
  if(!housing||!costs)return;
  const heading=housing.querySelector(':scope > h3'),number=heading.querySelector('.num');
  heading.replaceChildren(number,document.createTextNode(' 寮と暮らし｜街・住居'));
  const label=[...housing.querySelectorAll('.topic-label')].find(el=>el.textContent.trim()==='公共交通・都市へのアクセス');
  const transit=label?.closest('.transit-box')||label?.closest('p');
  if(transit){transit.classList.add('transit-box','transit-reference');label.textContent='参考｜公共交通・都市へのアクセス';costs.append(transit);}
}
